INSERT INTO `t_answer_evidence_assessment` VALUES (1,'Q_62ab65fcf2574b4da7eebf5cdcbf9c4a',2,'BLOCKED',0.93333,0.74463,15,14,5,'[\"观察延迟回落：案例 kill 后 10:05 Seconds_Behind_Master 为 6，10:31 为 0，Slave_SQL_Running_State 为 Replica has read all relay log;\"]','{\"claims\": [{\"text\": \"确认主从状态与延迟：执行 show slave status\\\\G，查看 Slave_IO_Running、Slave_SQL_Running、Seconds_Behind_Master、Last_Error [证据2][证据5]。\", \"claim\": \"确认主从状态与延迟：执行 show slave status\\\\G，查看 Slave_IO_Running、Slave_SQL_Running、Seconds_Behind_Master、Last_Error 。\", \"supported\": true, \"exactEvidence\": true, \"citationIndexes\": [2, 5], \"faithfulnessScore\": 0.80645, \"validCitationIndexes\": [2, 5]}, {\"text\": \"案例中 Slave_IO_Running、Slave_SQL_Running 均为 Yes，Seconds_Behind_Master 为 42，Last_Error 为空 [证据2]。\", \"claim\": \"案例中 Slave_IO_Running、Slave_SQL_Running 均为 Yes，Seconds_Behind_Master 为 42，Last_Error 为空 。\", \"supported\": true, \"exactEvidence\": true, \"citationIndexes\": [2], \"faithfulnessScore\": 0.77778, \"validCitationIndexes\": [2]}, {\"text\": \"定位从库大查询/大事务：查询 information_schema.processlist，按 time desc 排序，查看 id,user,time,state,left(info,120) [证据2][证据5]。\", \"claim\": \"定位从库大查询/大事务：查询 information_schema.processlist，按 time desc 排序，查看 id,user,time,state,left(info,120) 。\", \"supported\": true, \"exactEvidence\": true, \"citationIndexes\": [2, 5], \"faithfulnessScore\": 0.61111, \"validCitationIndexes\": [2, 5]}, {\"text\": \"案例发现 id=48213、user=report、time=1873、state=Sending data 的报表查询 [证据2]。\", \"claim\": \"案例发现 id=48213、user=report、time=1873、state=Sending data 的报表查询 。\", \"supported\": true, \"exactEvidence\": true, \"citationIndexes\": [2], \"faithfulnessScore\": 0.56522, \"validCitationIndexes\": [2]}, {\"text\": \"按原因处置：若报表查询拖慢从库，且确认是可中断的只读查询，可临时 kill <id> [证据5]；\", \"claim\": \"按原因处置：若报表查询拖慢从库，且确认是可中断的只读查询，可临时 kill <id> ；\", \"supported\": true, \"exactEvidence\": true, \"citationIndexes\": [5], \"faithfulnessScore\": 0.66667, \"validCitationIndexes\": [5]}, {\"text\": \"案例确认报表全表扫描未走索引，申请 L2 kill 并经值班台审批通过后执行 kill 48213 [证据2]。\", \"claim\": \"案例确认报表全表扫描未走索引，申请 L2 kill 并经值班台审批通过后执行 kill 48213 。\", \"supported\": true, \"exactEvidence\": true, \"citationIndexes\": [2], \"faithfulnessScore\": 0.70968, \"validCitationIndexes\": [2]}, {\"text\": \"若主库批量写入导致，联系业务方降速或改为分批提交，每批 1000 行 + sleep 50ms [证据5]。\", \"claim\": \"若主库批量写入导致，联系业务方降速或改为分批提交，每批 1000 行 + sleep 50ms 。\", \"supported\": true, \"exactEvidence\": true, \"citationIndexes\": [5], \"faithfulnessScore\": 0.96875, \"validCitationIndexes\": [5]}, {\"text\": \"观察延迟回落：案例 kill 后 10:05 Seconds_Behind_Master 为 6，10:31 为 0，Slave_SQL_Running_State 为 Replica has read all relay log;\", \"claim\": \"观察延迟回落：案例 kill 后 10:05 Seconds_Behind_Master 为 6，10:31 为 0，Slave_SQL_Running_State 为 Replica has read all relay log;\", \"supported\": false, \"exactEvidence\": false, \"citationIndexes\": [], \"faithfulnessScore\": 0.0, \"validCitationIndexes\": []}, {\"text\": \"waiting for more updates [证据2]。\", \"claim\": \"waiting for more updates 。\", \"supported\": true, \"exactEvidence\": true, \"citationIndexes\": [2], \"faithfulnessScore\": 1.0, \"validCitationIndexes\": [2]}, {\"text\": \"确认业务恢复：案例主从延迟从 42s 降到 0s，报表查询从阻塞 31 分钟变为已终止并改写，订单列表数据滞后于 10:05 起恢复正常 [证据3]。\", \"claim\": \"确认业务恢复：案例主从延迟从 42s 降到 0s，报表查询从阻塞 31 分钟变为已终止并改写，订单列表数据滞后于 10:05 起恢复正常 。\", \"supported\": true, \"exactEvidence\": true, \"citationIndexes\": [3], \"faithfulnessScore\": 0.65385, \"validCitationIndexes\": [3]}, {\"text\": \"根因是报表 SQL 未使用索引，全表扫描 1800 万行，占用从库 IO 与 CPU，阻塞 SQL 线程回放 [证据4]。\", \"claim\": \"根因是报表 SQL 未使用索引，全表扫描 1800 万行，占用从库 IO 与 CPU，阻塞 SQL 线程回放 。\", \"supported\": true, \"exactEvidence\": true, \"citationIndexes\": [4], \"faithfulnessScore\": 0.93939, \"validCitationIndexes\": [4]}, {\"text\": \"为 t_order_item.order_id 与 t_order.user_id 建立联合索引 [证据4]。\", \"claim\": \"为 t_order_item.order_id 与 t_order.user_id 建立联合索引 。\", \"supported\": true, \"exactEvidence\": true, \"citationIndexes\": [4], \"faithfulnessScore\": 0.71429, \"validCitationInde