INSERT INTO `t_evaluation_case` VALUES (21,'EC_1fb9bc563f94430b803e7c83d930d946',1,'rm -rf / 属于什么等级的命令','[\"03-高危命令清单与审批处置规范.md\"]','[]','L1 不可逆/全局影响；拦截 + 二次确认 + 双签','[\"L1\", \"OPS-L1\"]','L1','v1','ACTIVE','2026-10-08 22:23:21'),(22,'EC_c927b670a50f4ff39c2794c20aa4c721',1,'chmod -R 777 为什么不能用','[\"03-高危命令清单与审批处置规范.md\"]','[]','L2，全域开放造成权限敞口，应精确到 750/640','[\"L1\", \"OPS-L1\"]','L1','v1','ACTIVE','2026-10-08 22:23:21'),(23,'EC_b159338db8394ce8bca70b751fd02349',1,'redis-cli FLUSHALL 的替代方案','[\"03-高危命令清单与审批处置规范.md\", \"07-中间件运维手册-Redis与Kafka.md\"]','[]','L2；按前缀 `--scan` 删除，或用 allkeys-lru','[\"L1\", \"OPS-L1\"]','L1','v1','ACTIVE','2026-10-08 22:23:21'),(24,'EC_83ea9dae1832476dae3903f6198bcb58',1,'会话 SES-2026-08-12-00631 做了什么','[\"13-运维命令操作记录-CL-2026-08-0163-K8s滚动发布回滚.md\"]','[]','pay-api v2.8.3 灰度后回滚至 v2.8.2','[\"L1\", \"OPS-L1\"]','L1','v1','ACTIVE','2026-10-08 22:23:21'),(25,'EC_1bf00ac4574448f9bd90a330055a666c',1,'归档 AUD-2026-08-19-00788 是什么事件','[\"14-高危命令拦截事件-IC-2026-08-0009-外包人员rm误删拦截.md\"]','[]','外包刘洋 `rm -rf /` 被 L1 拦截，账号冻结 30 天','[\"L1\", \"OPS-L1\"]','L1','v1','ACTIVE','2026-10-08 22:23:21'),(26,'EC_9198180edce44ffe9942d4175c850080',1,'srv-pay-01 的磁盘清理是谁做的','[\"11-运维命令操作记录-CL-2026-08-0142-磁盘清理.md\"]','[]','张伟（E10231），释放约 44G，工单 ITSM-2026-08-0743','[\"L1\", \"OPS-L1\"]','L1','v1','ACTIVE','2026-10-08 22:23:21'),(27,'EC_92939e0fedd841cf9c6a12e206fbb5b9',1,'db-mysql-03 的用途是什么','[\"05-MySQL数据库运维与故障处置手册.md\"]','[]','延迟 1 小时的从库，用于误操作快速恢复','[\"L1\", \"OPS-L1\"]','L1','v1','ACTIVE','2026-10-08 22:23:21'),(28,'EC_06f3e4b3ce0c4dfd8863e48ff297c785',1,'外包账号默认有效期是多少天','[\"02-主机与账号权限管理规范.md\", \"15-运维FAQ常见问题30问.md\"]','[]','30 天，到期自动停用，操作强制录屏留存 180 天','[\"L1\", \"OPS-L1\"]','L1','v1','ACTIVE','2026-10-08 22:23:22'),(29,'EC_647cbea950b043f1aea2282a9f801d18',1,'删了日志但磁盘还是满的怎么回事','[\"04-Linux主机巡检与故障排查操作手册.md\"]','[]','句柄未释放，`lsof +L1` 查 deleted 文件后处理','[\"L2\", \"OPS-L2\"]','L2','v1','ACTIVE','2026-10-08 22:23:22'),(30,'EC_676fb11f738b415bb52f8b13463bc9b0',1,'数据库卡住了，从库数据一直不更新