INSERT INTO `t_index_outbox` VALUES (1,'76978ae6-d56d-4d1b-8b1c-76ba145ec66c','DOCUMENT_CHUNKS:3:1',2,'DOCUMENT','KB:2:DOCUMENT:3','DOCUMENT_CHUNKS_UPSERT',1,'/ai/index/chunks','{\"eventId\": \"76978ae6-d56d-4d1b-8b1c-76ba145ec66c\", \"documentId\": 3, \"indexVersion\": 1, \"knowledgeBaseId\": 2}','SUCCEEDED',1,8,'2026-10-08 20:08:47',NULL,NULL,NULL,'{\"total\": 340, \"indexed\": 7, \"external\": {\"milvus\": {\"indexed\": 7, \"provider\": \"milvus\"}, \"elasticsearch\": {\"indexed\": 7, \"provider\": \"elasticsearch\"}}}','2026-10-08 20:08:47','2026-10-08 20:08:51','2026-10-08 20:08:51'),(2,'4c477695-9680-4a59-97f1-8d40e66522b3','DOCUMENT_CHUNKS:1:1',2,'DOCUMENT','KB:2:DOCUMENT:1','DOCUMENT_CHUNKS_UPSERT',1,'/ai/index/chunks','{\"eventId\": \"4c477695-9680-4a59-97f1-8d40e66522b3\", \"documentId\": 1, \"indexVersion\": 1, \"knowledgeBaseId\": 2}','SUCCEEDED',1,8,'2026-10-08 20:08:47',NULL,NULL,NULL,'{\"total\": 347, \"indexed\": 7, \"external\": {\"milvus\": {\"indexed\": 7, \"provider\": \"milvus\"}, \"elasticsearch\": {\"indexed\": 7, \"provider\": \"elasticsearch\"}}}','2026-10-08 20:08:47','2026-10-08 20:08:53','2026-10-08 20:08:53'),(3,'3ff9a09f-34ff-4291-af09-6cb62e1455f3','DOCUMENT_CHUNKS:2:1',2,'DOCUMENT','KB:2:DOCUMENT:2','DOCUMENT_CHUNKS_UPSERT',1,'/ai/index/chunks','{\"eventId\": \"3ff9a09f-34ff-4291-af09-6cb62e1455f3\", \"documentId\": 2, \"indexVersion\": 1, \"knowledgeBaseId\": 2}','SUCCEEDED',1,8,'2026-10-08 20:08:47',NULL,NULL,NULL,'{\"total\": 354, \"indexed\": 7, \"external\": {\"milvus\": {\"indexed\": 7, \"provider\": \"milvus\"}, \"elasticsearch\": {\"indexed\": 7, \"provider\": \"elasticsearch\"}}}','2026-10-08 20:08:47','2026-10-08 20:08:54','2026-10-08 20:08:54'),(4,'5018af62-15c6-4434-b467-154fc784b94f','DOCUMENT_STANDARD:2:1',2,'DOCUMENT','KB:2:STANDARD:2','DOCUMENT_STANDARD_UPSERT',1,'/ai/standard/index','{\"units\": [{\"seq\": 1, \"content\": \"运维组织与值班职责规范\\n\\n文件编号：OPS-RULE-01　|　版本：V3.1　|　生效日期：2026-07-01　|　有效期至：2027-06-30\\n\\n适用对象：运维部全体（SRE 组、DBA 组、中间件组、值班台）、外包驻场与厂商支持人员\\n\\n归口部门：运维部　|　审批人：王强（运维总监，工号 E10087）\\n\\n一、目的与适用范围\\n\\n本规范用于明确运维团队的岗位设置、值班安排、职责边界与交接要求，避免故障发生时出现「不知道找谁」「两个人同时改同一个配置」「值班人不知道自己该做什么」三类问题。适用于蓝湖科技全部生产、预发、测试环境以及堡垒主机、监控平台的运维活动。\\n\\n二、组织与岗位设置\\n\\n运维部下设三个组与一个值班台，岗位与职责如下。\", \"page_no\": null, \"unit_id\": \"U1\", \"char_end\": 321, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"HEADING\", \"char_start\": 0, \"chunk_type\": \"HEADING\", \"token_count\": 175, \"content_hash\": \"01f864a00da2fb1e7f04678084d75d8fe0cab757c1af6c7a20badb54f73b4c58\", \"heading_path\": \"运维组织与值班职责规范\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 2, \"content\": \"岗位: SRE 工程师；编制: 8；主要职责: 主机、容器、发布变更、容量与稳定性；值班要求: 参与 7×24 轮值\\n岗位: DBA；编制: 3；主要职责: MySQL / Redis 实例、备份恢复、慢查询治理；值班要求: 参与 7×24 轮值（二线）\\n岗位: 中间件工程师；编制: 3；主要职责: Kafka、Elasticsearch、Nginx、消息队列；值班要求: 工作日值班 + 二线\\n岗位: 安全审计员；编制: 2；主要职责: 堡垒主机审计、高危操作复核、合规抽查；值班要求: 不参与轮值，随时响应审计\\n岗位: 值班台（OpsDesk）；编制: 4；主要职责: 告警首响、工单分派、升级通知、变更窗口登记；值班要求: 7×24 坐班\", \"page_no\": null, \"unit_id\": \"U2\", \"char_end\": 646, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"TABLE\", \"char_start\": 323, \"chunk_type\": \"TABLE\", \"token_count\": 157, \"content_hash\": \"4c5354bf099cb5fa3f3248abd1217435661bb45476f12485a60a2ab86e11bcf7\", \"heading_path\": \"运维组织与值班职责规范 / 二、组织与岗位设置\", \"overlap_prefix\": \"避免故障发生时出现「不知道找谁」「两个人同时改同一个配置」「值班人不知道自己该做什么」三类问题。适用于蓝湖科技全部生产、预发、测试环境以及堡垒主机、监控平台的运维活动。\\n\\n二、组织与岗位设置\\n\\n运维部下设三个组与一个值班台，岗位与职责如下。\", \"parent_unit_id\": null}, {\"seq\": 3, \"content\": \"三、值班制度\\n\\n3.1 班次安排\\n\\n白班：09:00–21:00，值班台 1 人 + SRE 1 人；\\n\\n夜班：21:00–次日 09:00，值班台 1 人 + SRE 1 人（远程 oncall）；\\n\\nDBA 与中间件工程师为二线值班，不做坐班，但必须在 15 分钟内响应升级呼叫；\\n\\n排班以周为单位滚动，每周五 18:00 前由值班台发布下周排班表。\\n\\n3.2 值班纪律\\n\\n值班人员必须保持手机、企业微信、电话三种联系方式同时在线；\\n\\n值班期间不得安排需要离开工位超过 30 分钟的事项，确需离开须找同级替班并在排班表注明；\\n\\n值班人员禁止在未经审批的情况下执行 L1 高危命令（见 OPS-RULE-03）；\\n\\n交接班必须完成《值班交接单》，未完成交接不得离岗。\\n\\n四、职责边界（RACI）\\n\\n故障处置过程中的角色分工按下表执行，避免多头指挥。\", \"page_no\": null, \"unit_id\": \"U3\", \"char_end\": 1023, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"HEADING\", \"char_start\": 648, \"chunk_type\": \"HEADING\", \"token_count\": 192, \"content_hash\": \"e8e67dbef010d3ba699d2604c7dc52fc761cb56ed26270dd776b44ba000a8e25\", \"heading_path\": \"运维组织与值班职责规范 / 三、值班制度\", \"overlap_prefix\": \"安全审计员；编制: 2；主要职责: 堡垒主机审计、高危操作复核、合规抽查；值班要求: 不参与轮值，随时响应审计\\n岗位: 值班台（OpsDesk）；编制: 4；主要职责: 告警首响、工单分派、升级通知、变更窗口登记；值班要求: 7×24 坐班\", \"parent_unit_id\": null}, {\"seq\": 4, \"content\": \"环节: 告警首响（5 分钟内）；值班台: R；SRE: C；DBA: —；中间件: —；业务负责人: I\\n环节: 影响面判断；值班台: C；SRE: R；DBA: C；中间件: C；业务负责人: C\\n环节: 止损操作（回滚 / 切流 / 限流）；值班台: A；SRE: R；DBA: C；中间件: C；业务负责人: I\\n环节: 根因定位；值班台: I；SRE: R；DBA: R；中间件: R；业务负责人: C\\n环节: 对外通报；值班台: R；SRE: C；DBA: I；中间件: I；业务负责人: A\\n环节: 复盘与改进项跟踪；值班台: C；SRE: R；DBA: C；中间件: C；业务负责人: A\", \"page_no\": null, \"unit_id\": \"U4\", \"char_end\": 1326, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"TABLE\", \"char_start\": 1025, \"chunk_type\": \"TABLE\", \"token_count\": 127, \"content_hash\": \"97d9ae1a472b7bbbbeefbf2163013f099045b668d0572a71e8493fc24bd02dc9\", \"heading_path\": \"运维组织与值班职责规范 / 四、职责边界（RACI）\", \"overlap_prefix\": \"班并在排班表注明；\\n\\n值班人员禁止在未经审批的情况下执行 L1 高危命令（见 OPS-RULE-03）；\\n\\n交接班必须完成《值班交接单》，未完成交接不得离岗。\\n\\n四、职责边界（RACI）\\n\\n故障处置过程中的角色分工按下表执行，避免多头指挥。\", \"parent_unit_id\": null}, {\"seq\": 5, \"content\": \"R=负责执行，A=最终责任，C=被咨询，I=被告知\\n\\n五、交接班要求\\n\\n交接班须在《值班交接单》中记录以下内容，缺项视为交接未完成：\\n\\n当班期间发生的告警与处置结果（含工单号）；\\n\\n未闭环的事项与下一步动作；\\n\\n正在执行的变更窗口与预计结束时间；\\n\\n需要下一班重点关注的服务（如灰度中、压测中、限流中）。\", \"page_no\": null, \"unit_id\": \"U5\", \"char_end\": 1480, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"QUOTE\", \"char_start\": 1328, \"chunk_type\": \"PARAGRAPH\", \"token_count\": 89, \"content_hash\": \"df83f93de8e9e5e19aa58a9c5120ed626c105a6603728dbe5758b1d22f983521\", \"heading_path\": \"运维组织与值班职责规范 / 四、职责边界（RACI）\", \"overlap_prefix\": \"R；DBA: R；中间件: R；业务负责人: C\\n环节: 对外通报；值班台: R；SRE: C；DBA: I；中间件: I；业务负责人: A\\n环节: 复盘与改进项跟踪；值班台: C；SRE: R；DBA: C；中间件: C；业务负责人: A\", \"parent_unit_id\": null}, {\"seq\": 6, \"content\": \"值班交接单 · 2026-08-12 白班 → 夜班\\n交接人：张伟（E10231）　接班人：刘洋（E10944）\\n1) 13:42 srv-pay-01 磁盘 87%，已清理日志至 63%，工单 ITSM-2026-08-0881 未闭环\\n2) 16:10 支付服务灰度 v2.8.3（30% 流量），预计 21:30 全量，需夜班观察 P99\\n3) 重点观察：db-mysql-01 主从延迟（峰值 4.2s），DBA 李娜已在跟进\", \"page_no\": null, \"unit_id\": \"U6\", \"char_end\": 1699, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"CODE\", \"char_start\": 1482, \"chunk_type\": \"CODE\", \"token_count\": 84, \"content_hash\": \"a997e031c052b87a06fe2d540330aba820b83c1621d443a31410f25950cd26ac\", \"heading_path\": \"运维组织与值班职责规范 / 五、交接班要求\", \"overlap_prefix\": \"要求\\n\\n交接班须在《值班交接单》中记录以下内容，缺项视为交接未完成：\\n\\n当班期间发生的告警与处置结果（含工单号）；\\n\\n未闭环的事项与下一步动作；\\n\\n正在执行的变更窗口与预计结束时间；\\n\\n需要下一班重点关注的服务（如灰度中、压测中、限流中）。\", \"parent_unit_id\": null}, {\"seq\": 7, \"content\": \"六、违规处理\\n\\n漏岗、失联：第一次通报批评，第二次计入季度绩效扣分；\\n\\n未交接离岗导致故障扩大的，按《员工奖惩管理办法》认定为重大过失；\\n\\n值班期间违规执行高危命令的，一律按一级违规处理，并暂停其堡垒主机权限 30 天。\\n\\n七、附则\\n\\n本规范由运维部归口解释，与《高危命令清单与审批处置规范》《监控告警与分级响应机制》配套执行。三者条款冲突时，以最新生效日期的文件为准，并由归口部门在 5 个工作日内发布修订通知。\", \"page_no\": null, \"unit_id\": \"U7\", \"char_end\": 1908, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"HEADING\", \"char_start\": 1701, \"chunk_type\": \"HEADING\", \"token_count\": 127, \"content_hash\": \"5ce09b0e7391a6dfc2db6124ef5b11759bb01f971a07ce4326af4236f7e6c521\", \"heading_path\": \"运维组织与值班职责规范 / 六、违规处理\", \"overlap_prefix\": \" ITSM-2026-08-0881 未闭环\\n2) 16:10 支付服务灰度 v2.8.3（30% 流量），预计 21:30 全量，需夜班观察 P99\\n3) 重点观察：db-mysql-01 主从延迟（峰值 4.2s），DBA 李娜已在跟进\", \"parent_unit_id\": null}], \"eventId\": \"5018af62-15c6-4434-b467-154fc784b94f\", \"sourceId\": 3, \"standard\": {\"stats\": {\"chars\": 1908, \"units\": 7, \"blocks\": 37, \"tables\": 2, \"tokens\": 951, \"sections\": 10, \"chunkPolicy\": {\"measure\": \"CHAR\", \"strategy\": \"SEMANTIC\", \"chunkSize\": 900, \"parentChild\": false, \"chunkOverlap\": 120, \"minChunkSize\": 120, \"keepStructure\": true, \"respectSentence\": true}, \"chunkStrategy\": \"SEMANTIC\"}, \"title\": \"运维组织与值班职责规范\", \"doc_id\": \"8b5b668db611da81ddde27809b8d7ef5\", \"sha256\": \"dad4e2d1e460f56dea55ffbee9de912f2808e936d5a0001a8166226946385d2e\", \"language\": \"zh\", \"page_count\": 0, \"source_format\": \"MARKDOWN\"}, \"sourceUri\": \"upload://01-运维组织与值班职责规范.md\", \"documentId\": 2, \"sourceName\": \"01-运维组织与值班职责规范.md\", \"indexVersion\": 1, \"permissionTags\": \"[\\\"ops\\\",\\\"sre\\\",\\\"dba\\\"]\", \"knowledgeBaseId\": 2}','SUCCEEDED',1,8,'2026-10-08 20:08:47',NULL,NULL,NULL,'{\"units\": 7, \"documentId\": 2, \"elasticsearch\": {\"target\": \"llmkb_standard_doc_v1\", \"provider\": \"elasticsearch\", \"standardIndexed\": 7}, \"knowledgeBaseId\": 2}','2026-10-08 20:08:47','2026-10-08 20:08:55','2026-10-08 20:08:55'),(5,'ad46e556-1025-4ac6-81f0-97c160c1af18','DOCUMENT_STANDARD:1:1',2,'DOCUMENT','KB:2:STANDARD:1','DOCUMENT_STANDARD_UPSERT',1,'/ai/standard/index','{\"units\": [{\"seq\": 1, \"content\": \"高危命令清单与审批处置规范\\n\\n文件编号：OPS-RULE-03　|　版本：V4.0　|　生效日期：2026-06-20　|　有效期至：2027-06-19\\n\\n归口部门：运维部　|　审批人：王强（E10087）　|　复核：陈静（安全审计员，E10612）\\n\\n一、命令分级\\n\\n生产环境命令按破坏半径分为三级，L1 为最高危。分级与处置动作如下。\", \"page_no\": null, \"unit_id\": \"U1\", \"char_end\": 170, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"HEADING\", \"char_start\": 0, \"chunk_type\": \"HEADING\", \"token_count\": 79, \"content_hash\": \"4ae610cd46652d444a35a06ce2fad0051334069544f7bb19011ffe2f37428199\", \"heading_path\": \"高危命令清单与审批处置规范\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 2, \"content\": \"等级: L1；判定标准: 不可逆、影响全局或多租户；典型命令: rm -rf /、drop database、kubectl delete ns、iptables -F、useradd -o -u 0；处置动作: 拦截 + 二次确认 + 实时告警；审批要求: 运维总监 + 安全审计员双签\\n等级: L2；判定标准: 影响单服务但可恢复；典型命令: chmod -R 777、redis-cli FLUSHALL、kubectl scale --replicas=0、truncate table；处置动作: 阻断并转审批流；审批要求: 直属主管 + 值班台\\n等级: L3；判定标准: 影响配置或局部；典型命令: systemctl restart、nginx -s reload、kill -9；处置动作: 记录 + 事后抽查；审批要求: 值班台登记即可\", \"page_no\": null, \"unit_id\": \"U2\", \"char_end\": 549, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"TABLE\", \"char_start\": 172, \"chunk_type\": \"TABLE\", \"token_count\": 152, \"content_hash\": \"89ca3a367f4013a6c1287bcce1311120337a65560cf65e4a3ef0317b527233ee\", \"heading_path\": \"高危命令清单与审批处置规范 / 一、命令分级\", \"overlap_prefix\": \"026-06-20　|　有效期至：2027-06-19\\n\\n归口部门：运维部　|　审批人：王强（E10087）　|　复核：陈静（安全审计员，E10612）\\n\\n一、命令分级\\n\\n生产环境命令按破坏半径分为三级，L1 为最高危。分级与处置动作如下。\", \"parent_unit_id\": null}, {\"seq\": 3, \"content\": \"二、完整高危命令清单（节选）\", \"page_no\": null, \"unit_id\": \"U3\", \"char_end\": 565, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"HEADING\", \"char_start\": 551, \"chunk_type\": \"HEADING\", \"token_count\": 8, \"content_hash\": \"359ddc0478c3f029dae6e08be6f7b92c9fb916465c2b80908cade8f13bb2904e\", \"heading_path\": \"高危命令清单与审批处置规范 / 二、完整高危命令清单（节选）\", \"overlap_prefix\": \"转审批流；审批要求: 直属主管 + 值班台\\n等级: L3；判定标准: 影响配置或局部；典型命令: systemctl restart、nginx -s reload、kill -9；处置动作: 记录 + 事后抽查；审批要求: 值班台登记即可\", \"parent_unit_id\": null}, {\"seq\": 4, \"content\": \"命令: rm -rf / 或 rm -rf /*；等级: L1；风险说明: 删除根目录，系统不可恢复；推荐替代方案: 使用 rm 指定具体目录，先 ls 确认\\n命令: rm -rf；等级: L1；风险说明: 误删应用目录导致服务不可用；推荐替代方案: 先备份至 /data/backup，再执行\\n命令: drop database / drop table；等级: L1；风险说明: 数据不可逆丢失；推荐替代方案: 走 DBA 审批，先做全量备份\\n命令: truncate table；等级: L2；风险说明: 快速清空表，binlog 不可回滚；推荐替代方案: 改用带条件的 delete + 备份\\n命令: update set ...（无 where）；等级: L2；风险说明: 全表误更新；推荐替代方案: 必须带 where 并先 select 验证\\n命令: chmod -R 777；等级: L2；风险说明: 全域开放权限，造成权限敞口；推荐替代方案: 精确到 750/640 与属主\\n命令: chown -R root:root；等级: L2；风险说明: 应用失去写权限；推荐替代方案: 指定应用属主 app:app\\n命令: redis-cli FLUSHALL；等级: L2；风险说明: 缓存全清导致数据库雪崩；推荐替代方案: 按 key 前缀删除 redis-cli --scan\\n命令: kubectl delete ns；等级: L1；风险说明: 删除命名空间及全部资源；推荐替代方案: 使用 kubectl scale 或删除单个资源\\n命令: kubectl scale --replicas=0 deploy/；等级: L2；风险说明: 服务缩容至零，业务中断；推荐替代方案: 缩容到最小值 1 或使用暂停发布\\n命令: iptables -F；等级: L1；风险说明: 清空防火墙规则，暴露端口；推荐替代方案: 逐条删除规则\\n命令: history -c；等级: L1；风险说明: 清除操作痕迹，视为违规；推荐替代方案: 禁止执行\\n命令: useradd -o -u 0；等级: L1；风险说明: 创建影子 root 账号；推荐替代方案: 禁止执行\\n命令: systemctl stop；等级: L2；风险说明: 服务中断；推荐替代方案: 走变更窗口与审批\", \"page_no\": null, \"unit_id\": \"U4\", \"char_end\": 1556, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"TABLE\", \"char_start\": 567, \"chunk_type\": \"TABLE\", \"token_count\": 440, \"content_hash\": \"d009febead687b54ab3f9c886e5f1fe781394a55c69d4ffa6f5549f17aebf271\", \"heading_path\": \"高危命令清单与审批处置规范 / 二、完整高危命令清单（节选）\", \"overlap_prefix\": \"二、完整高危命令清单（节选）\", \"parent_unit_id\": null}, {\"seq\": 5, \"content\": \"三、拦截与处置流程\", \"page_no\": null, \"unit_id\": \"U5\", \"char_end\": 1567, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"HEADING\", \"char_start\": 1558, \"chunk_type\": \"HEADING\", \"token_count\": 6, \"content_hash\": \"3be9525286b718a7223ff845a3329519a156024be6e574afd7142e55a138975e\", \"heading_path\": \"高危命令清单与审批处置规范 / 三、拦截与处置流程\", \"overlap_prefix\": \"案: 禁止执行\\n命令: useradd -o -u 0；等级: L1；风险说明: 创建影子 root 账号；推荐替代方案: 禁止执行\\n命令: systemctl stop；等级: L2；风险说明: 服务中断；推荐替代方案: 走变更窗口与审批\", \"parent_unit_id\": null}, {\"seq\": 6, \"content\": \"命令输入 → 堡垒主机实时匹配规则库\\n   ├─ L1 命中 → 立即拦截 + 弹窗二次确认（需输入工单号）+ 告警推送值班台与安全审计员\\n   ├─ L2 命中 → 阻断并转审批流（主管 + 值班台），审批通过后 30 分钟内有效\\n   └─ L3 命中 → 放行并记录，事后按 5% 比例抽查\", \"page_no\": null, \"unit_id\": \"U6\", \"char_end\": 1717, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"CODE\", \"char_start\": 1569, \"chunk_type\": \"CODE\", \"token_count\": 75, \"content_hash\": \"b7c19a0084b92f6445393dedac72b35c5862594cfc660428144fa64badf29ea2\", \"heading_path\": \"高危命令清单与审批处置规范 / 三、拦截与处置流程\", \"overlap_prefix\": \"三、拦截与处置流程\", \"parent_unit_id\": null}, {\"seq\": 7, \"content\": \"被拦截的命令必须关联 ITSM 工单号，无工单号的 L1/L2 命令一律不得放行。\\n\\n四、实时告警与审计\\n\\nL1 命中：企业微信「高危操作」群 + 电话呼叫值班台与安全审计员，5 分钟内必须有人认领；\\n\\n每次拦截生成审计记录，字段包含：会话 ID、操作人、主机、命令原文、等级、处置结果、关联工单；\\n\\n审计记录同步至 KosAudit，留存 180 天，供月度审计与合规抽查调阅。\\n\\n五、例外与紧急处置\\n\\n故障止损场景下，若审批链路会显著扩大故障影响，允许先执行后补审：\\n\\n执行人电话通知值班台与安全审计员，获得口头授权；\\n\\n执行后 30 分钟内在 ITSM 补开工单并填写原因、影响与恢复情况；\\n\\n安全审计员在 24 小时内完成复核，未补单的按一级违规处理。\\n\\n六、违规处理\\n\\n绕过拦截（如通过脚本、管道、变量拼接规避匹配）：一级违规，暂停权限 30 天；\\n\\n执行 history -c、rm -rf /、创建影子账号等：立即终止会话、冻结账号并启动安全事件调查；\\n\\n外包与外部厂商人员触发 L1：终止合作并留存证据。\\n\\n七、与告警分级的关系\\n\\n高危命令拦截事件统一按《监控告警与分级响应机制》定为 P1 告警，即使未造成业务影响，也必须在 30 分钟内完成认领与说明。\", \"page_no\": null, \"unit_id\": \"U7\", \"char_end\": 2255, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"PARAGRAPH\", \"char_start\": 1719, \"chunk_type\": \"PARAGRAPH\", \"token_count\": 300, \"content_hash\": \"1b96db76d7495c0a7be5b27ce68bb2f45fca568ae23e65bd0e0f2487f2600f08\", \"heading_path\": \"高危命令清单与审批处置规范 / 三、拦截与处置流程\", \"overlap_prefix\": \"命中 → 立即拦截 + 弹窗二次确认（需输入工单号）+ 告警推送值班台与安全审计员\\n   ├─ L2 命中 → 阻断并转审批流（主管 + 值班台），审批通过后 30 分钟内有效\\n   └─ L3 命中 → 放行并记录，事后按 5% 比例抽查\", \"parent_unit_id\": null}], \"eventId\": \"ad46e556-1025-4ac6-81f0-97c160c1af18\", \"sourceId\": 1, \"standard\": {\"stats\": {\"chars\": 2255, \"units\": 7, \"blocks\": 26, \"tables\": 2, \"tokens\": 1060, \"sections\": 8, \"chunkPolicy\": {\"measure\": \"CHAR\", \"strategy\": \"SEMANTIC\", \"chunkSize\": 900, \"parentChild\": false, \"chunkOverlap\": 120, \"minChunkSize\": 120, \"keepStructure\": true, \"respectSentence\": true}, \"chunkStrategy\": \"SEMANTIC\"}, \"title\": \"高危命令清单与审批处置规范\", \"doc_id\": \"9c524f7b60c9947da022a2481a313495\", \"sha256\": \"a9bf8682f656178c677dda78b32aad7ccf5001466c60623e584a06f14529408c\", \"language\": \"zh\", \"page_count\": 0, \"source_format\": \"MARKDOWN\"}, \"sourceUri\": \"upload://03-高危命令清单与审批处置规范.md\", \"documentId\": 1, \"sourceName\": \"03-高危命令清单与审批处置规范.md\", \"indexVersion\": 1, \"permissionTags\": \"[\\\"ops\\\",\\\"sre\\\",\\\"dba\\\"]\", \"knowledgeBaseId\": 2}','SUCCEEDED',1,8,'2026-10-08 20:08:47',NULL,NULL,NULL,'{\"units\": 7, \"documentId\": 1, \"elasticsearch\": {\"target\": \"llmkb_standard_doc_v1\", \"provider\": \"elasticsearch\", \"standardIndexed\": 7}, \"knowledgeBaseId\": 2}','2026-10-08 20:08:47','2026-10-08 20:08:55','2026-10-08 20:08:55'),(6,'de7eadce-efb3-4050-8b0b-67dda8a76459','DOCUMENT_STANDARD:3:1',2,'DOCUMENT','KB:2:STANDARD:3','DOCUMENT_STANDARD_UPSERT',1,'/ai/standard/index','{\"units\": [{\"seq\": 1, \"content\": \"主机与账号权限管理规范\\n\\n文件编号：OPS-RULE-02　|　版本：V2.4　|　生效日期：2026-05-15　|　有效期至：2027-05-14\\n\\n归口部门：运维部（安全审计员复核）　|　审批人：王强（E10087）\\n\\n一、账号分类与命名\\n\\n生产环境账号分为四类，命名与用途如下表。所有账号必须绑定实名，禁止共享账号。\", \"page_no\": null, \"unit_id\": \"U1\", \"char_end\": 162, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"HEADING\", \"char_start\": 0, \"chunk_type\": \"HEADING\", \"token_count\": 79, \"content_hash\": \"93e3f813ae74df5c3574c2b86e49f1f53cb451aacd2cd53655c3c43e268901da\", \"heading_path\": \"主机与账号权限管理规范\", \"overlap_prefix\": \"\", \"parent_unit_id\": null}, {\"seq\": 2, \"content\": \"类别: 人员账号；命名规则: 姓名拼音，如 zhangwei；用途: 运维人员登录堡垒主机；默认有效期: 在职期间，每季度复核\\n类别: 资源账号；命名规则: 服务名，如 app / mysql / redis；用途: 应用与中间件运行身份；默认有效期: 长期，随资源下线回收\\n类别: 特权账号；命名规则: root / k8sops；用途: 紧急维护；默认有效期: 仅审批后临时启用，单次 4 小时\\n类别: 外部账号；命名规则: v；用途: 厂商支持与外包驻场；默认有效期: 30 天，到期自动停用\", \"page_no\": null, \"unit_id\": \"U2\", \"char_end\": 413, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"TABLE\", \"char_start\": 164, \"chunk_type\": \"TABLE\", \"token_count\": 128, \"content_hash\": \"8ce5a57e68b0e6a87d426e53963fb6869818641befc76b8f02367263d3b470d7\", \"heading_path\": \"主机与账号权限管理规范 / 一、账号分类与命名\", \"overlap_prefix\": \"生效日期：2026-05-15　|　有效期至：2027-05-14\\n\\n归口部门：运维部（安全审计员复核）　|　审批人：王强（E10087）\\n\\n一、账号分类与命名\\n\\n生产环境账号分为四类，命名与用途如下表。所有账号必须绑定实名，禁止共享账号。\", \"parent_unit_id\": null}, {\"seq\": 3, \"content\": \"二、权限申请与审批\\n\\n申请人通过 OA 提交《生产环境权限申请单》，写明主机清单、账号类型、操作范围、有效期；\\n\\n权限审批链：直属主管 → 运维值班台 → 安全审计员（涉及 root 或生产数据库时加签运维总监）；\\n\\n审批通过后由堡垒主机（KosBastion 4.2）自动下发，权限到期自动回收；\\n\\n禁止通过工单以外的任何方式（口头、群消息、邮件）授予生产权限。\", \"page_no\": null, \"unit_id\": \"U3\", \"char_end\": 597, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"HEADING\", \"char_start\": 415, \"chunk_type\": \"HEADING\", \"token_count\": 101, \"content_hash\": \"b8fb48b6eeecd87fc993f3376bde90389b1af99715f019d378d8d171a2c1adf1\", \"heading_path\": \"主机与账号权限管理规范 / 二、权限申请与审批\", \"overlap_prefix\": \"，随资源下线回收\\n类别: 特权账号；命名规则: root / k8sops；用途: 紧急维护；默认有效期: 仅审批后临时启用，单次 4 小时\\n类别: 外部账号；命名规则: v；用途: 厂商支持与外包驻场；默认有效期: 30 天，到期自动停用\", \"parent_unit_id\": null}, {\"seq\": 4, \"content\": \"# 权限下发后在堡垒主机核对（示例：查询 zhangwei 的可登录主机与有效期）\\nkosbastion-cli user show zhangwei\\n# 输出示例\\n# user: zhangwei (E10231)\\n# hosts: srv-pay-01, srv-pay-02, srv-order-03, srv-gateway-01\\n# accounts: app, deploy\\n# expiresAt: 2026-11-14 23:59\", \"page_no\": null, \"unit_id\": \"U4\", \"char_end\": 823, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"CODE\", \"char_start\": 599, \"chunk_type\": \"CODE\", \"token_count\": 70, \"content_hash\": \"10a0e622ee1df0fe510e06f903a3a10156ea4b38215c2bf8cf5d14e706842dc0\", \"heading_path\": \"主机与账号权限管理规范 / 二、权限申请与审批\", \"overlap_prefix\": \"：直属主管 → 运维值班台 → 安全审计员（涉及 root 或生产数据库时加签运维总监）；\\n\\n审批通过后由堡垒主机（KosBastion 4.2）自动下发，权限到期自动回收；\\n\\n禁止通过工单以外的任何方式（口头、群消息、邮件）授予生产权限。\", \"parent_unit_id\": null}, {\"seq\": 5, \"content\": \"三、外包与外部厂商账号\\n\\n外包驻场与厂商人员只能使用外部账号，有效期上限 30 天；\\n\\n外部账号默认禁止执行 L1/L2 高危命令，确需执行的须由内部人员陪同并双人复核；\\n\\n外部人员的所有操作强制录屏并全量留存，留存期 180 天；\\n\\n合作结束后 24 小时内禁用账号并导出其操作审计归档。\\n\\n四、特权账号使用\\n\\nroot 权限默认关闭，需通过堡垒主机「临时提权」申请，审批人为运维总监或安全审计员；\\n\\n单次提权有效期 4 小时，到期自动回收，系统记录提权原因与操作序列；\\n\\n提权期间执行的每一条命令进入高危命令实时检测通道（见 OPS-RULE-03）。\\n\\n五、账号清理与复核\", \"page_no\": null, \"unit_id\": \"U5\", \"char_end\": 1114, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"HEADING\", \"char_start\": 825, \"chunk_type\": \"HEADING\", \"token_count\": 167, \"content_hash\": \"9c4a85399031e7db30d5aa8179c448256f0f39fe89f556b495051b611e01a9f0\", \"heading_path\": \"主机与账号权限管理规范 / 三、外包与外部厂商账号\", \"overlap_prefix\": \"231)\\n# hosts: srv-pay-01, srv-pay-02, srv-order-03, srv-gateway-01\\n# accounts: app, deploy\\n# expiresAt: 2026-11-14 23:59\", \"parent_unit_id\": null}, {\"seq\": 6, \"content\": \"周期: 每月；动作: 扫描 90 天未登录账号，通知确认后停用；责任人: 值班台\\n周期: 每季度；动作: 全量账号实名复核，回收离职人员账号；责任人: 安全审计员\\n周期: 离职当天；动作: 立即停用账号、回收密钥、导出审计归档；责任人: 值班台 + 安全审计员\\n周期: 资源下线；动作: 同步回收该资源上的全部资源账号；责任人: SRE\", \"page_no\": null, \"unit_id\": \"U6\", \"char_end\": 1284, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"TABLE\", \"char_start\": 1116, \"chunk_type\": \"TABLE\", \"token_count\": 96, \"content_hash\": \"2579766d3274d6f81363f0732716fd1d450799058fc6ce766898a840601506a9\", \"heading_path\": \"主机与账号权限管理规范 / 五、账号清理与复核\", \"overlap_prefix\": \"需通过堡垒主机「临时提权」申请，审批人为运维总监或安全审计员；\\n\\n单次提权有效期 4 小时，到期自动回收，系统记录提权原因与操作序列；\\n\\n提权期间执行的每一条命令进入高危命令实时检测通道（见 OPS-RULE-03）。\\n\\n五、账号清理与复核\", \"parent_unit_id\": null}, {\"seq\": 7, \"content\": \"六、违规处理\\n\\n共享账号、借用他人账号：一级违规，暂停权限 30 天并通报；\\n\\n私自增设账号或绕过堡垒主机直连生产：一级违规，按《员工奖惩管理办法》处理；\\n\\n权限过期未及时回收造成敞口的，追究审批人与资源负责人责任。\\n\\n七、配套系统\\n\\n本规范通过堡垒主机 KosBastion 4.2 强制执行，审计数据同步至日志审计平台 KosAudit，数据库操作另由 DB-Audit 独立留存。三个系统的账号主体必须一致，差异以本规范为准。\", \"page_no\": null, \"unit_id\": \"U7\", \"char_end\": 1502, \"page_end\": null, \"strategy\": \"SEMANTIC\", \"block_type\": \"HEADING\", \"char_start\": 1286, \"chunk_type\": \"HEADING\", \"token_count\": 121, \"content_hash\": \"36afc184670319829c001b4b992c06d7958dd1a6a477af7096283c7cb2eb4087\", \"heading_path\": \"主机与账号权限管理规范 / 六、违规处理\", \"overlap_prefix\": \"；动作: 全量账号实名复核，回收离职人员账号；责任人: 安全审计员\\n周期: 离职当天；动作: 立即停用账号、回收密钥、导出审计归档；责任人: 值班台 + 安全审计员\\n周期: 资源下线；动作: 同步回收该资源上的全部资源账号；责任人: SRE\", \"parent_unit_id\": null}], \"eventId\": \"de7eadce-efb3-4050-8b0b-67dda8a76459\", \"sourceId\": 2, \"standard\": {\"stats\": {\"chars\": 1502, \"units\": 7, \"blocks\": 29, \"tables\": 2, \"tokens\": 762, \"sections\": 8, \"chunkPolicy\": {\"measure\": \"CHAR\", \"strategy\": \"SEMANTIC\", \"chunkSize\": 900, \"parentChild\": false, \"chunkOverlap\": 120, \"minChunkSize\": 120, \"keepStructure\": true, \"respectSentence\": true}, \"chunkStrategy\": \"SEMANTIC\"}, \"title\": \"主机与账号权限管理规范\", \"doc_id\": \"fbf6c06c279255a002b37f9053e81374\", \"sha256\": \"eb80d8650465e411769b1cbd59174f8c674bc3ab6be0add681f48b10ca6eb5fd\", \"language\": \"zh\", \"page_count\": 0, \"source_format\": \"MARKDOWN\"}, \"sourceUri\": \"upload://02-主机与账号权限管理规范.md\", \"documentId\": 3, \"sourceName\": \"02-主机与账号权限管理规范.md\", \"indexVersion\": 1, \"permissionTags\": \"[\\\"ops\\\",\\\"sre\\\",\\\"dba\\\"]\", \"knowledgeBaseId\": 2}','SUCCEEDED',1,8,'2026-10-08 20:08:47',NULL,NULL,NULL,'{\"units\": 7, \"documentId\": 3, \"elasticsearch\": {\"target\": \"llmkb_standard_doc_v1\", \"provider\": \"elasticsearch\", \"standardIndexed\": 7}, \"knowledgeBaseId\": 2}','2026-10-08 20:08:47','2026-10-08 20:08:55','2026-10-08 20:08:55'),(7,'0974a3c9-6f49-45ab-9cf6-2fb13ecf70e7','CARD_CREATE:K_685180d1926b4217ae82ae5d84cc72f3:1',2,'CARD','KB:2:CARD:K_685180d1926b4217ae82ae5d84cc72f3','KNOWLEDGE_OBJECT_UPSERT',1,'/ai/index/knowledge','{\"cards\": [{\"type\": \"PROBLEM_SOLUTION\", \"title\": \"运维组织与值班职责规范\", \"status\": \"DRAFT\", \"content\": \"运维组织与值班职责规范\\n\\n文件编号：OPS-RULE-01　|　版本：V3.1　|　生效日期：2026-07-01　|　有效期至：2027-06-30\\n\\n适用对象：运维部全体（SRE 组、DBA 组、中间件组、值班台）、外包驻场与厂商支持人员\\n\\n归口部门：运维部　|　审批人：王强（运维总监，工号 E10087）\\n\\n一、目的与适用范围\\n\\n本规范用于明确运维团队的岗位设置、值班安排、职责边界与交接要求，避免故障发生时出现「不知道找谁」「两个人同时改同一个配置」「值班人不知道自己该做什么」三类问题。适用于蓝湖科技全部生产、预发、测试环境以及堡垒主机、监控平台的运维活动。\\n\\n二、组织与岗位设置\\n\\n运维部下设三个组与一个值班台，岗位与职责如下。\", \"summary\": \"运维组织与值班职责规范\\n\\n文件编号：OPS-RULE-01　|　版本：V3.1　|　生效日期：2026-07-01　|　有效期至：2027-06-30\\n\\n适用对象：运维部全体（SRE 组、DBA 组、中间件组、值班台）、外包驻场与厂商支持人员\\n\\n归口部门：运维部　|　审批人：王强（运维总监，工号 E10087）\\n\\n一、目的与适用范围\\n\\n本规范用于明确运维团队的岗位设置、值班安排、职责边界与交接要求，避免故障发生时出现「不知道找谁」「两个人同时改同一个配置」「值班人不知道自己该\", \"confidence\": 0.68, \"updated_at\": \"2026-10-08 20:09:50\", \"entity_codes\": [\"运维组织与值班职责规范\", \"OPS-RULE-01\", \"V3.1\", \"SRE\", \"DBA\", \"E10087\", \"监控平台\", \"二、组织与岗位设置\"], \"evidence_ids\": [\"EVD_cecc85b44ba242db8d7534ed5a57cb9f\"], \"evidence_code\": \"EVD_cecc85b44ba242db